        const ef = [`CFD\uFF1A\u79FB\u5230 <b>${st}</b> \u5E36`, `\u5DE5\u4F5C\u53F0 WIP \u2192 <b>${wip()}</b>`];
        if (st === "Done" && e.started) ef.push(`Cycle Time \u65B0\u6A23\u672C <b>${ddiff(e.started, e.done)} \u5929</b>`, ...effFlow());
