    const OP_WEEKDAYS = [["MO", "\u4E00"], ["TU", "\u4E8C"], ["WE", "\u4E09"], ["TH", "\u56DB"], ["FR", "\u4E94"], ["SA", "\u516D"], ["SU", "\u65E5"]];
